import{_ as t,o as s,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Candidatures","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/candidatures.md","filePath":"src/guide/secretariat/candidatures.md"}'),i={name:"guide/secretariat/candidatures.md"};function n(o,e,l,u,d,c){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="candidatures" tabindex="-1">Candidatures <a class="header-anchor" href="#candidatures" aria-label="Permalink to &quot;Candidatures&quot;">​</a></h1><p>La page <strong>Dossiers à traiter</strong> liste toutes les candidatures déposées pour une inscription, qu&#39;elles viennent du formulaire public rempli par une famille (canal <strong>En ligne</strong>) ou d&#39;une saisie faite par la caisse pour une famille venue sur site (canal <strong>Caisse</strong>). C&#39;est depuis cette page que vous décidez d&#39;accepter ou de refuser chaque dossier.</p><p>Les familles accèdent au formulaire public par le bouton <strong>Inscrire mon enfant</strong> de la page d&#39;accueil de l&#39;établissement.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Consulter la file d&#39;attente est toujours disponible. L&#39;affectation à une classe (la validation d&#39;un dossier) dépend du module Admissions activé pour votre établissement — si le bouton <strong>Valider</strong> n&#39;apparaît pas, contactez votre administrateur.</p></div><h2 id="consulter-la-file-d-attente" tabindex="-1">Consulter la file d&#39;attente <a class="header-anchor" href="#consulter-la-file-d-attente" aria-label="Permalink to &quot;Consulter la file d&#39;attente&quot;">​</a></h2><p>La page affiche pour chaque dossier le nom de l&#39;élève, le site souhaité, le département souhaité, le canal et le statut :</p><table tabindex="0"><thead><tr><th>Statut</th><th>Signification</th></tr></thead><tbody><tr><td>En attente</td><td>Le dossier n&#39;a pas encore été traité</td></tr><tr><td>Validé</td><td>L&#39;élève a été affecté à une classe</td></tr><tr><td>Refusé</td><td>Le dossier a été refusé, avec un motif consigné</td></tr></tbody></table><p>Utilisez le champ de recherche pour retrouver un dossier par nom, et le filtre de statut pour n&#39;afficher que les dossiers en attente, validés ou refusés. Cliquez sur <strong>Examiner</strong> sur la ligne d&#39;un dossier pour l&#39;ouvrir.</p><h2 id="examiner-un-dossier" tabindex="-1">Examiner un dossier <a class="header-anchor" href="#examiner-un-dossier" aria-label="Permalink to &quot;Examiner un dossier&quot;">​</a></h2><p>La page de détail d&#39;un dossier vous montre :</p><ul><li>la <strong>date de naissance</strong> de l&#39;élève, le <strong>site</strong> et le <strong>département</strong> souhaités, et le <strong>canal</strong> (En ligne ou Caisse) ;</li><li>si le dossier a été saisi par la caisse, le nom de la personne qui l&#39;a <strong>saisi</strong> ;</li><li>la liste des <strong>parents / tuteurs</strong> avec leur nom, e-mail, téléphone et lien de parenté ; le contact principal porte une étiquette <strong>Contact principal</strong> ;</li><li>la liste des <strong>documents</strong> joints au dossier, avec qui les a ajoutés (un membre de l&#39;équipe, ou <strong>Soumis en ligne</strong> si la famille les a déposés elle-même via le formulaire public) — cliquez sur <strong>Télécharger</strong> pour ouvrir un document.</li></ul><p>Si aucun document n&#39;a été joint, la page l&#39;indique clairement.</p><h2 id="valider-un-dossier" tabindex="-1">Valider un dossier <a class="header-anchor" href="#valider-un-dossier" aria-label="Permalink to &quot;Valider un dossier&quot;">​</a></h2><ol><li>Ouvrez le dossier depuis <strong>Examiner</strong>.</li><li>Dans le bloc <strong>Affecter à une classe</strong>, choisissez la <strong>classe</strong> dans la liste. Chaque classe affiche son occupation actuelle (par exemple <code>24/30</code>, ou <code>∞</code> si elle n&#39;a pas de capacité maximale définie).</li><li>Si la classe a atteint sa capacité, vous ne pouvez pas la sélectionner normalement : cochez <strong>Forcer l&#39;affectation même si la classe a atteint sa capacité</strong> pour l&#39;assigner malgré tout.</li><li>Cliquez sur <strong>Valider</strong>.</li></ol><p>L&#39;élève est alors inscrit dans la classe choisie et son dossier financier devient visible pour la caisse dans <strong>Facturation</strong> — voir <a href="/era-guide/guide/caissier/inscriptions-et-paiements.html">Inscriptions et paiements</a>.</p><h2 id="refuser-un-dossier" tabindex="-1">Refuser un dossier <a class="header-anchor" href="#refuser-un-dossier" aria-label="Permalink to &quot;Refuser un dossier&quot;">​</a></h2><ol><li>Ouvrez le dossier depuis <strong>Examiner</strong>.</li><li>Cliquez sur <strong>Refuser</strong>.</li><li>Dans la fenêtre de confirmation, indiquez le <strong>Motif de refus</strong> (ce champ est obligatoire).</li><li>Confirmez en cliquant à nouveau sur <strong>Refuser</strong>.</li></ol><p>Le motif de refus reste consigné sur le dossier et reste consultable par la suite.</p>',18)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
